class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int countBalancedPermutations(String num) {
    int n = num.length(), sum = 0;
    int[] cnt = new int[10];
    for (int i = 0; i < n; i++) {
      cnt[num.charAt(i) - '0']++;
      sum += num.charAt(i) - '0';
    }
    if (sum % 2 != 0) return 0;
    int half = sum / 2, a = (n + 1) / 2, b = n / 2;
    long[] f = new long[n + 1], inv = new long[n + 1];
    f[0] = 1;
    for (int i = 1; i <= n; i++) f[i] = f[i - 1] * i % MOD;
    for (int i = 0; i <= n; i++) inv[i] = pow(f[i], MOD - 2);
    long[][] dp = new long[a + 1][half + 1];
    dp[0][0] = 1;
    for (int d = 0; d < 10; d++) {
      long[][] nd = new long[a + 1][half + 1];
      for (int k = 0; k <= a; k++) {
        for (int s = 0; s <= half; s++) {
          long v = dp[k][s];
          if (v == 0) continue;
          for (int c = 0; c <= cnt[d] && k + c <= a && s + d * c <= half; c++) {
            nd[k + c][s + d * c] =
                (nd[k + c][s + d * c] + v * inv[c] % MOD * inv[cnt[d] - c]) % MOD;
          }
        }
      }
      dp = nd;
    }
    return (int) (dp[a][half] * f[a] % MOD * f[b] % MOD);
  }
}
